import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame } from '../game/neon.js';

test('Ball should bounce off brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // Row 0, Col 0

  // Position ball so it's about to hit the bottom of the brick from above (vy > 0)
  // Actually, let's hit the top face (ball coming from below, vy < 0)
  // Brick 0 is at y: BRICK_TOP (48), h: 20. Top is 48, Bottom is 68.
  // Ball: r=7. Bottom of ball is y+7.
  // To hit the bottom face: ball is at y=70, vy = -100. Next frame it's at y=65.

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below the brick
  state.ball.vy = -100; // Moving UP
  state.ball.vx = 0;

  const mockCtx = {
    fillRect: () => {},
    arc: () => {},
    fill: () => {},
    beginPath: () => {},
    fillText: () => {},
    fillStyle: '',
  };

  // One frame of collision
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced (vy flipped)');
});

import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, WIDTH, HEIGHT } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
  fillStyle: '',
};

function setupBall(state, x, y, vx, vy) {
  state.ball.x = x;
  state.ball.y = y;
  state.ball.vx = vx;
  state.ball.vy = vy;
}

test('D1: No bounce - Bottom hit', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // Row 0, Col 0
  setupBall(state, brick.x + brick.w / 2, brick.y + brick.h + 2, 0, -100);
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced (vy flipped)');
});

test('D3: Wrong axis - Side hit', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  setupBall(state, brick.x - 2, brick.y + brick.h / 2, 100, 0);
  frame(mockCtx, state);
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced (vx flipped)');
});

test('D2: Sticky - Overlap resolution', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  setupBall(state, brick.x + brick.w / 2, brick.y + 2, 0, 100);
  frame(mockCtx, state);
  // Ball was at y+2, vy=100. It should be pushed above the brick.
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'Ball should be pushed out of the brick');
});

test('D4: Double inversion - Seam', () => {
  const state = createState(1);
  // Bricks 0 and 1 are in same row, adjacent.
  const b0 = state.bricks[0];
  const b1 = state.bricks[1];
  // Place ball so it overlaps both on the bottom edge
  state.ball.x = b0.x + b0.w - 2; // overlaps b0 and b1
  state.ball.y = b0.y + b0.h + 2; 
  state.ball.vy = -100;
  state.ball.vx = 0;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy, 100, 'Ball should have bounced once, not twice');
});

test('D5: Tunneling - High speed', () => {
  const state = createState(6); // Level 6
  const brick = state.bricks[0];
  // Ball at y, next frame y + 35.5. 
  // Brick is at y_b to y_b + 20.
  // We want it to skip the collision.
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; // Bottom is at -3.
  // We need to simulate the step and frame.
  // In the game: step() moves ball, then frame() checks collision.

  // Instead of using frame(), let's manually move it like step() would.
  const dt = 0.05;
  state.ball.vy = 710; 
  state.ball.y += state.ball.vy * dt; // y = brick.y - 10 + 35.5 = brick.y + 25.5
  // Ball top is now 25.5 - 7 = 18.5. Brick bottom is 20.
  // Wait, if it's at 18.5, it still overlaps!
  // Let's try to make it truly tunnel.
  // Brick h = 20. Ball d = 14. Total 34.
  // If it moves 35.5, it can tunnel if it starts just above.
  state.ball.y = brick.y - 8; // bottom = -1
  state.ball.y += 35.5; // y = brick.y + 27.5. top = 20.5.
  // Now it's completely below the brick.

  // Now call frame(). It should detect collision if it's a swept AABB.
  // But current impl is discrete.
  frame(mockCtx, state);

  // This is tricky because frame() doesn't know the previous position.
  // I'll mark this as "cannot be tested with current frame() signature" 
  // and focus on the other ones first, or suggest moving collision logic.
});
```
